// Flatten the webhook payload + the adjudicator response into one item
// so every downstream node reads from a single, predictable shape.
const cfg = $('Config').first().json;
const verdict = $input.first().json;
const payload = cfg.body;

return [{
  json: {
    // config
    adjudicatorUrl: cfg.adjudicatorUrl,
    adminEmail: cfg.adminEmail,
    fromEmail: cfg.fromEmail,
    // who we are writing to
    customerEmail: payload.customer && payload.customer.email ? payload.customer.email : '',
    // the original request, needed again when we ask for the final draft
    payload,
    // the adjudication response (verdict, lane, citedClauses, caseFile, ...)
    ...verdict,
  },
}];

// Build the Clause 12.5 case email: full Case File, the system proposal with
// its cited clauses, and one-click approve/amend controls.
//
// Each control is a link back into THIS paused execution. n8n exposes the
// resume URL as $execution.resumeUrl; the query string carries the adjudicator's
// choice, which the next node turns into a confirm/amend record (Clause 15.2).
const c = $('Build case').first().json;
const hr = c.humanReview || {};
const cf = c.caseFile || {};
const resume = $execution.resumeUrl;

const url = (outcome, v) => {
  const sep = resume.includes('?') ? '&' : '?';
  return `${resume}${sep}outcome=${outcome}&verdict=${encodeURIComponent(v)}&case=${encodeURIComponent(c.requestId)}`;
};

const button = (href, label, bg) =>
  `<a href="${href}" style="display:inline-block;margin:4px 6px 4px 0;padding:9px 16px;`
  + `background:${bg};color:#fff;text-decoration:none;border-radius:6px;`
  + `font:600 13px/1.2 system-ui,sans-serif">${label}</a>`;

const proposed = hr.proposedFinalVerdict;
const controls = [];
if (proposed) {
  controls.push(button(url('approve', proposed), `Approve — ${proposed}`, '#2E7D4F'));
}
for (const option of (hr.options || [])) {
  if (option === proposed) continue;
  controls.push(button(url('amend', option), `Amend → ${option}`, '#3B4E8C'));
}

const rows = [
  ['Order', `${cf.orderId} — ${cf.itemName}`],
  ['SKU / category', `${cf.sku} / ${cf.category}`],
  ['Invoice value', `Rs ${Number(cf.invoiceValue || 0).toLocaleString('en-IN')}`],
  ['Payment mode', cf.paymentMode],
  ['Delivered', `${cf.deliveryDate} (day ${cf.daysSinceDelivery} of a ${cf.windowDays ?? '-'}-day window)`],
  ['Reason code', cf.reasonCode],
  ['Evidence', `${cf.evidenceRequired ? 'required' : 'not required'} / ${cf.photoAttached ? 'attached' : 'none attached'}`],
  ['Flags', Object.entries(cf.flags || {}).filter(([, v]) => v).map(([k]) => k).join(', ') || 'none'],
  ['Intake channel', cf.intakeChannel],
  ['Customer', c.customerEmail],
].map(([k, v]) => `<tr><td style="padding:4px 14px 4px 0;color:#5C5E58">${k}</td><td style="padding:4px 0"><b>${v ?? ''}</b></td></tr>`).join('');

const clauses = (c.supportingClauses || [])
  .slice(0, 8)
  .map(x => `<li><b>${x.clause}</b> — ${String(x.text).slice(0, 260).replace(/\n/g, ' ')}</li>`)
  .join('');

const priority = hr.priority
  ? `<p style="background:#F7E7E7;color:#A93B3B;padding:10px 14px;border-radius:6px;
       font:600 13px system-ui"> PRIORITY ${hr.priority} — Clause 5.4.2 routes this to
       Quality &amp; Compliance within 4 business hours.</p>`
  : '';

const html = `<div style="font:14px/1.55 system-ui,sans-serif;color:#20211F;max-width:680px">
  <h2 style="margin:0 0 2px">Returns case ${c.requestId}</h2>
  <p style="margin:0 0 16px;color:#5C5E58">Routed to human review &middot; escalation:
     <b>${hr.escalationKind || '-'}</b> &middot; confidence: <b>${c.confidence}</b></p>
  ${priority}
  <h3 style="margin:18px 0 6px">Case file (Clause 12.1)</h3>
  <table style="border-collapse:collapse;font-size:13px">${rows}</table>
  <h3 style="margin:18px 0 6px">System proposal (Clause 12.5)</h3>
  <p style="margin:0 0 6px"><b>${proposed || 'No verdict proposed'}</b></p>
  <p style="margin:0 0 8px;color:#5C5E58">${hr.proposalBasis || ''}</p>
  <p style="margin:0 0 4px"><b>Why it escalated:</b> ${c.reasoning}</p>
  <p style="margin:0;font-family:ui-monospace,monospace;font-size:12px;color:#3B4E8C">
     Cited: ${(c.citedClauses || []).join(' &middot; ')}</p>
  <h3 style="margin:18px 0 6px">Clauses in play</h3>
  <ul style="margin:0;padding-left:18px;font-size:13px;color:#5C5E58">${clauses}</ul>
  <h3 style="margin:20px 0 8px">Your decision</h3>
  <div>${controls.join('')}</div>
  <p style="margin:14px 0 0;font-size:12px;color:#5C5E58">
     One click records the outcome, sends the customer their verdict email, and closes
     the case. The customer has already received a holding email (Clause 12.4) and has
     been told to expect a decision within 24 business hours.</p>
</div>`;

return [{ json: { ...c, adminSubject: `[${hr.escalationKind || 'review'}] ${c.requestId} — ${c.caseFile ? c.caseFile.itemName : ''}`, adminHtml: html } }];

// Turn the adjudicator's click into a confirm/amend record.
const raw = $input.first().json || {};
const q = raw.query || {};
const c = $('Build case').first().json;
const proposed = (c.humanReview || {}).proposedFinalVerdict;

let outcome = q.outcome === 'approve' ? 'confirmed'
            : q.outcome === 'amend' ? 'amended'
            : null;
let finalVerdict = q.verdict || null;

if (!outcome) {
  // The resume request did not surface a query string. Rather than silently
  // recording the wrong thing, fall back to the system proposal only when there
  // is one, and otherwise fail loudly with what we actually received.
  if (!proposed) {
    throw new Error(
      'The resume request carried no ?outcome=/?verdict=, and the engine proposed no '
      + 'verdict for this case, so there is nothing safe to record. Keys received: '
      + Object.keys(raw).join(', ')
    );
  }
  outcome = 'confirmed';
  finalVerdict = proposed;
}

finalVerdict = finalVerdict || proposed;
if (!finalVerdict) {
  throw new Error('No final verdict could be determined from the approval link.');
}

return [{
  json: {
    ...c,
    outcome,
    finalVerdict,
    adjudicator: q.by || '',
    note: q.note || '',
  },
}];

// Daily FYI digest of auto-lane verdicts (Clause 12.5) plus the
// Clause 15.2 amendment-rate control.
const metrics = $input.first().json;
const rows = ($('Get decisions').first().json.decisions || []);
const cfg = $('Digest Config').first().json;

const since = Date.now() - 24 * 60 * 60 * 1000;
const recent = rows.filter(r => new Date(r.timestamp).getTime() >= since);
const auto = recent.filter(r => r.decidedBy === 'engine' && r.lane === 'AUTO');
const escalated = recent.filter(r => r.decidedBy === 'engine' && r.lane === 'HUMAN_REVIEW');
const humanRows = recent.filter(r => r.decidedBy === 'human');

const cell = v => `<td style="padding:6px 12px 6px 0;border-bottom:1px solid #E3E2DA">${v ?? ''}</td>`;
const line = r => `<tr>
  ${cell(`<code>${r.caseId}</code>`)}
  ${cell((r.caseFile && r.caseFile.order ? r.caseFile.order.itemName : '') || '')}
  ${cell(`<b>${r.verdict}</b>`)}
  ${cell(r.confidence)}
  ${cell((r.citedClauses || []).join(', '))}
</tr>`;

const kpi = metrics.humanAdjudication || {};
const st = metrics.straightThrough || {};
const warn = kpi.breachesClause15_2
  ? `<p style="background:#F7E7E7;color:#A93B3B;padding:10px 14px;border-radius:6px">
       <b>Clause 15.2 breach.</b> Adjudicators amended ${kpi.amendmentRatePct}% of system
       proposals over the last ${metrics.windowDays} days, above the ${kpi.ceilingPct}%
       ceiling. Review the divergence log and either fix the engine logic or amend the
       policy document.</p>`
  : '';

const html = `<div style="font:14px/1.55 system-ui,sans-serif;color:#20211F;max-width:760px">
  <h2 style="margin:0 0 4px">Rivaya returns — daily digest</h2>
  <p style="margin:0 0 16px;color:#5C5E58">No action required. Auto-lane verdicts issued in
     the last 24 hours, and the rolling ${metrics.windowDays}-day control numbers.</p>
  ${warn}
  <p style="margin:0 0 14px">
    <b>${auto.length}</b> auto verdicts &middot;
    <b>${escalated.length}</b> escalated to review &middot;
    <b>${humanRows.length}</b> closed by an adjudicator<br>
    Straight-through rate (${metrics.windowDays}d): <b>${st.autoRatePct ?? '-'}%</b> &middot;
    amendment rate: <b>${kpi.amendmentRatePct ?? 'n/a'}%</b> &middot;
    median engine latency: <b>${metrics.latency ? metrics.latency.avgMs : '-'} ms</b>
  </p>
  <table style="border-collapse:collapse;font-size:13px;width:100%">
    <tr style="text-align:left;color:#5C5E58">
      <th style="padding-bottom:6px">Case</th><th>Item</th><th>Verdict</th>
      <th>Confidence</th><th>Clauses</th>
    </tr>
    ${auto.map(line).join('') || '<tr><td colspan="5" style="padding:8px 0;color:#5C5E58">No auto-lane verdicts in the last 24 hours.</td></tr>'}
  </table>
</div>`;

return [{ json: { ...cfg, digestHtml: html, autoCount: auto.length } }];
